import type { EndpointDescriptor } from '../lib/ZigBeeNode';
import type { HandleFrameEvent } from '../manager/zigbee';
export type OnEventEvent = {
    args: HandleFrameEvent;
    return: void;
};
export type GetNodeEvent = {
    args: {
        token: string;
        endpointDescriptors: Array<EndpointDescriptor>;
    };
    return: {
        modelId: string;
        manufacturerName: string;
        ieeeAddress: string;
        receiveWhenIdle: boolean;
    };
};
export type SendFrameEvent = {
    args: {
        token: string;
        endpointId: number;
        clusterId: number;
        frame: Buffer;
    };
    return: void;
};
export type HomeyZigbeeEvents = {
    onEvent: OnEventEvent;
};
export type SDKZigbeeEvents = {
    getNode: GetNodeEvent;
    sendFrame: SendFrameEvent;
};
type BoundClient<TOmit extends string> = {
    emit: <T extends keyof SDKZigbeeEvents>(event: T, data?: Omit<SDKZigbeeEvents[T]['args'], TOmit>) => Promise<SDKZigbeeEvents[T]['return']>;
};
export type ZigbeeNodeClient = BoundClient<'token'>;
export {};
